def largestPool(heights):
    n = len(heights)
    water = [0] * n
    l, r = 0, n - 1
    lmax = rmax = 0
    while l < r:
        if heights[l] < heights[r]:
            if heights[l] > lmax:
                lmax = heights[l]
            water[l] = lmax - heights[l]
            l += 1
        else:
            if heights[r] > rmax:
                rmax = heights[r]
            water[r] = rmax - heights[r]
            r -= 1
    best = cur = 0
    for w in water:
        if w > 0:
            cur += w
            if cur > best:
                best = cur
        else:
            cur = 0
    return best
